p=argparse.ArgumentParser();p.add_argument('--pose',default='side');p.add_argument('--profile',default='P0');p.add_argument('--seed',type=int,default=19000);a=p.parse_args();poses={'front':(.300,.16,math.pi/2),'edge':(.31,.23,-3*math.pi/4),'near':(.32,.25,math.pi),'nearer':(.315,.25,math.pi),'old':(.33,.27,math.pi),'side':(.305,.235,math.pi),'rear':(.235,.30,-math.pi/2),'diagonal':(.30,.235,-3*math.pi/4)};pose=poses[a.pose];w=ControlWorld(a.seed,True,start_task='laptop');w.d.qpos[:2]=pose[:2];w.d.qpos[3:7]=[math.cos(pose[2]/2),0,0,math.sin(pose[2]/2)];mujoco.mj_forward(w.m,w.d);w.frames=[];w.capture();r=w.do_task('laptop',next(p for p in PRESSES if p.code==a.profile));out=Path('mochi/artifacts/control-v8');out.mkdir(parents=True,exist_ok=True);source=Path('mochi/src/mochi/control_v8/manipulation.py').read_bytes();sha=hashlib.sha256(source).hexdigest();(out/f'controller-{sha[:12]}.py').write_bytes(source);(out/f'probe-{a.pose}-{a.profile}-{a.seed}-{uuid.uuid4().hex[:8]}.json').write_text(json.dumps({'result':r,'episode':w.episode(),'controller_sha256':sha},separators=(',',':')));print(a.pose,a.profile,json.dumps(r),flush=True)
